const bookingData = $('Normalize Booking Data').first().json;
let events = [];
try {
  const rawItems = $input.all().map(i => i.json);
  events = rawItems.filter(e => e && (e.start || e.summary));
} catch (err) {
  events = [];
}
const requestedStart = new Date(bookingData.start);
const durationMin = Number(bookingData.duration_min) || 60;
const requestedEnd = bookingData.end ? new Date(bookingData.end) : new Date(requestedStart.getTime() + durationMin * 60000);

const conflict = events.find(event => {
  let eStart, eEnd;
  if (event.start?.dateTime) {
    eStart = new Date(event.start.dateTime);
    eEnd = new Date(event.end.dateTime);
  } else if (event.start?.date) {
    eStart = new Date(event.start.date + 'T00:00:00');
    eEnd = new Date(event.end.date + 'T00:00:00');
  } else {
    return false;
  }
  return requestedStart < eEnd && requestedEnd > eStart;
});

return [{
  json: {
    available: !conflict,
    start: requestedStart.toISOString(),
    end: requestedEnd.toISOString(),
    ...bookingData
  }
}];

const eventDetails = $('Capture Event Details').first().json;
const bookingData = $('Normalize Booking Data').first().json;
const emailResult = $input.first().json;
const emailSent = !emailResult.error && (emailResult.id || emailResult.threadId);

return [{
  json: {
    success: true,
    partial: !emailSent,
    booking_id: bookingData.booking_id,
    event_id: eventDetails.event_id,
    calendar_link: eventDetails.calendar_link,
    meet_link: eventDetails.meet_link,
    start: eventDetails.confirmed_start,
    end: eventDetails.confirmed_end,
    timezone: eventDetails.timezone,
    email_sent: !!emailSent,
    message: emailSent ? 'Booking created and confirmation email sent.' : 'Event created, but confirmation email failed.'
  }
}];

const norm = $('Normalize Booking Data').first().json;
const capture = $('Capture Event Details').first().json;
return [{ json: {
  'Booking Id': norm.booking_id || '',
  'Created  Date': new Date().toISOString().split('T')[0],
  'Name': capture.attendee_name || norm.attendee_name || '',
  'Email': capture.attendee_email || norm.attendee_email || '',
  'Phone': capture.phone || norm.phone || '',
  'Topic': capture.event_title || capture.service_type || norm.event_title || '',
  'Booking Date': capture.booking_date || '',
  'Booking Time': capture.booking_time_12h || '',
  'Booking Status': 'confirmed',
  'Call ID': capture.call_id || norm.call_id || ''
} }];

